-- Database Aplikasi SPP & Tabungan TK
-- Import lewat phpMyAdmin (tab Import) atau jalankan: npm run setup

SET NAMES utf8mb4;
SET time_zone = '+07:00';
DROP DATABASE IF EXISTS `spp_tk`;
CREATE DATABASE `spp_tk` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `spp_tk`;

CREATE TABLE `pengaturan` (
  `id` TINYINT PRIMARY KEY,
  `nama_sekolah` VARCHAR(120) NOT NULL,
  `alamat` VARCHAR(255) NOT NULL DEFAULT '',
  `telepon` VARCHAR(30) NOT NULL DEFAULT '',
  `whatsapp` VARCHAR(20) NOT NULL DEFAULT '',
  `kepala_sekolah` VARCHAR(100) NOT NULL DEFAULT '',
  `bendahara` VARCHAR(100) NOT NULL DEFAULT '',
  `rekening` VARCHAR(160) NOT NULL DEFAULT '',
  `jatuh_tempo` TINYINT NOT NULL DEFAULT 10,
  `template_pengingat` TEXT NOT NULL,
  `fonnte_token` VARCHAR(120) NOT NULL DEFAULT '',
  `pengingat_otomatis` TINYINT(1) NOT NULL DEFAULT 0,
  `hari_pengingat` VARCHAR(40) NOT NULL DEFAULT '-3,0,7',
  `cron_key` CHAR(32) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE `pengguna` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nama` VARCHAR(100) NOT NULL,
  `username` VARCHAR(40) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `role` ENUM('admin','bendahara','guru') NOT NULL DEFAULT 'guru',
  `aktif` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL
) ENGINE=InnoDB;

-- Token sesi disimpan dalam bentuk hash SHA-256
CREATE TABLE `sesi` (
  `token` CHAR(64) PRIMARY KEY,
  `pengguna_id` INT NOT NULL,
  `expires_at` DATETIME NOT NULL,
  FOREIGN KEY (`pengguna_id`) REFERENCES `pengguna`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `kelas` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nama` VARCHAR(60) NOT NULL,
  `wali_kelas` VARCHAR(100) NOT NULL DEFAULT '',
  `tarif_spp` INT NOT NULL DEFAULT 0,
  `warna` VARCHAR(12) NOT NULL DEFAULT 'sage',
  `urutan` TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE `siswa` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `nis` VARCHAR(20) NOT NULL UNIQUE,
  `nama` VARCHAR(100) NOT NULL,
  `panggilan` VARCHAR(30) NOT NULL DEFAULT '',
  `jk` ENUM('L','P') NOT NULL,
  `tgl_lahir` DATE NOT NULL,
  `kelas_id` INT DEFAULT NULL,
  `nama_wali` VARCHAR(100) NOT NULL,
  `hubungan` VARCHAR(20) NOT NULL DEFAULT 'Ibu',
  `no_wa` VARCHAR(20) NOT NULL DEFAULT '',
  `alamat` VARCHAR(255) NOT NULL DEFAULT '',
  `potongan` INT NOT NULL DEFAULT 0,
  `ket_potongan` VARCHAR(80) NOT NULL DEFAULT '',
  `saldo_tabungan` INT NOT NULL DEFAULT 0,
  `status` ENUM('aktif','lulus','keluar') NOT NULL DEFAULT 'aktif',
  `token_wali` CHAR(24) NOT NULL UNIQUE,
  `tgl_masuk` DATE NOT NULL,
  `created_at` DATETIME NOT NULL,
  FOREIGN KEY (`kelas_id`) REFERENCES `kelas`(`id`) ON DELETE SET NULL,
  KEY `idx_siswa_kelas` (`kelas_id`, `status`)
) ENGINE=InnoDB;

-- Satu baris per tagihan. SPP memakai periode YYYY-MM dan tidak bisa dobel untuk bulan yang sama.
CREATE TABLE `tagihan` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `siswa_id` INT NOT NULL,
  `jenis` VARCHAR(40) NOT NULL,
  `periode` CHAR(7) DEFAULT NULL,
  `keterangan` VARCHAR(160) NOT NULL DEFAULT '',
  `nominal` INT NOT NULL,
  `potongan` INT NOT NULL DEFAULT 0,
  `terbayar` INT NOT NULL DEFAULT 0,
  `status` ENUM('belum','sebagian','lunas','batal') NOT NULL DEFAULT 'belum',
  `jatuh_tempo` DATE NOT NULL,
  `created_at` DATETIME NOT NULL,
  UNIQUE KEY `uq_tagihan_periode` (`siswa_id`, `jenis`, `periode`),
  KEY `idx_tagihan_status` (`status`, `jatuh_tempo`),
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE `pembayaran` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `no_kuitansi` VARCHAR(20) NOT NULL UNIQUE,
  `siswa_id` INT NOT NULL,
  `tanggal` DATETIME NOT NULL,
  `total` INT NOT NULL,
  `metode` ENUM('tunai','transfer','tabungan') NOT NULL DEFAULT 'tunai',
  `catatan` VARCHAR(160) NOT NULL DEFAULT '',
  `batal` TINYINT(1) NOT NULL DEFAULT 0,
  `dicatat_oleh` INT DEFAULT NULL,
  KEY `idx_bayar_tanggal` (`tanggal`),
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`dicatat_oleh`) REFERENCES `pengguna`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `pembayaran_detail` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `pembayaran_id` INT NOT NULL,
  `tagihan_id` INT NOT NULL,
  `jumlah` INT NOT NULL,
  FOREIGN KEY (`pembayaran_id`) REFERENCES `pembayaran`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`tagihan_id`) REFERENCES `tagihan`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Buku tabungan siswa: setiap setoran/penarikan satu baris, saldo_setelah = saldo berjalan
CREATE TABLE `tabungan` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `siswa_id` INT NOT NULL,
  `tanggal` DATETIME NOT NULL,
  `jenis` ENUM('setor','tarik') NOT NULL,
  `jumlah` INT NOT NULL,
  `saldo_setelah` INT NOT NULL,
  `keterangan` VARCHAR(160) NOT NULL DEFAULT '',
  `pembayaran_id` INT DEFAULT NULL,
  `dicatat_oleh` INT DEFAULT NULL,
  KEY `idx_tabungan_siswa` (`siswa_id`, `tanggal`),
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`pembayaran_id`) REFERENCES `pembayaran`(`id`) ON DELETE SET NULL,
  FOREIGN KEY (`dicatat_oleh`) REFERENCES `pengguna`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE `pengingat_log` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `siswa_id` INT NOT NULL,
  `tanggal` DATETIME NOT NULL,
  `kanal` ENUM('whatsapp','fonnte','otomatis') NOT NULL,
  `status` VARCHAR(20) NOT NULL DEFAULT 'terkirim',
  `total` INT NOT NULL DEFAULT 0,
  `pesan` TEXT NOT NULL,
  `oleh` INT DEFAULT NULL,
  KEY `idx_pengingat` (`siswa_id`, `tanggal`),
  FOREIGN KEY (`siswa_id`) REFERENCES `siswa`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`oleh`) REFERENCES `pengguna`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB;

