-- Sesuaikan tanggal data contoh dengan tanggal import
SET @geser = FLOOR(DATEDIFF(CURDATE(), '2026-11-03') / 7) * 7;
SET @bulan = PERIOD_DIFF(DATE_FORMAT(CURDATE(), '%Y%m'), 202611);
UPDATE pengguna SET created_at = created_at + INTERVAL @geser DAY;
UPDATE siswa SET tgl_masuk = tgl_masuk + INTERVAL @bulan MONTH, created_at = created_at + INTERVAL @bulan MONTH,
                 tgl_lahir = tgl_lahir + INTERVAL @bulan MONTH;
UPDATE tagihan SET periode = IF(periode IS NULL, NULL, DATE_FORMAT(STR_TO_DATE(CONCAT(periode, '-01'), '%Y-%m-%d') + INTERVAL @bulan MONTH, '%Y-%m')),
                   jatuh_tempo = jatuh_tempo + INTERVAL @bulan MONTH, created_at = created_at + INTERVAL @bulan MONTH
               ORDER BY id DESC;
UPDATE pembayaran SET tanggal = tanggal + INTERVAL @geser DAY;
UPDATE tabungan SET tanggal = tanggal + INTERVAL @geser DAY;
UPDATE pengingat_log SET tanggal = tanggal + INTERVAL @geser DAY;
